+class ContactForm {
+    constructor(rootElementId) {
+        this.rootElement = document.getElementById(rootElementId);
+        this.state = {
+            fullName: '',
+            email: '',
+            phoneNumber: '',
+            touched: {
+                fullName: false,
+                email: false,
+                phoneNumber: false
+            },
+            submitted: false
+        };
+        this.render();
+        this.attachEventListeners();
+    }
+
+    render() {
+        this.rootElement.innerHTML = `
+            <div class="contact-form-container">
+                <div class="contact-form-header">
+                    <h1>Get in Touch</h1>
+                    <p>We'd love to hear from you. Send us a message and we'll respond as soon as possible.</p>
+                </div>
+
+                <div id="successMessage" class="success-message">
+                    Thank you for contacting us! We'll be in touch soon.
+                </div>
+
+                <form id="contactForm" novalidate>
+                    <div class="form-field">
+                        <label for="fullName">
+                            Full Name
+                            <span class="required">*</span>
+                        </label>
+                        <input
+                            type="text"
+                            id="fullName"
+                            name="fullName"
+                            placeholder="John Doe"
+                            required
+                            value="${this.state.fullName}"
+                        >
+                        <div class="error-message" id="fullNameError"></div>
+                    </div>
+
+                    <div class="form-field">
+                        <label for="email">
+                            Email Address
+                            <span class="required">*</span>
+                        </label>
+                        <input
+                            type="email"
+                            id="email"
+                            name="email"
+                            placeholder="you@example.com"
+                            required
+                            value="${this.state.email}"
+                        >
+                        <div class="error-message" id="emailError"></div>
+                    </div>
+
+                    <div class="form-field">
+                        <label for="phoneNumber">
+                            Phone Number
+                        </label>
+                        <input
+                            type="tel"
+                            id="phoneNumber"
+                            name="phoneNumber"
+                            placeholder="(123) 456-7890"
+                            value="${this.state.phoneNumber}"
+                        >
+                        <div class="helper-text">Format: (123) 456-7890 or +1-800-000-0000</div>
+                        <div class="error-message" id="phoneNumberError"></div>
+                    </div>
+
+                    <button type="submit" class="submit-button">Send Message</button>
+                </form>
+            </div>
+        `;
+    }
+
+    attachEventListeners() {
+        const form = document.getElementById('contactForm');
+        const fullNameInput = document.getElementById('fullName');
+        const emailInput = document.getElementById('email');
+        const phoneNumberInput = document.getElementById('phoneNumber');
+
+        fullNameInput.addEventListener('input', (e) => {
+            this.state.fullName = e.target.value;
+            this.validate('fullName');
+        });
+
+        fullNameInput.addEventListener('blur', () => {
+            this.state.touched.fullName = true;
+            this.validate('fullName');
+        });
+
+        emailInput.addEventListener('input', (e) => {
+            this.state.email = e.target.value;
+            this.validate('email');
+        });
+
+        emailInput.addEventListener('blur', () => {
+            this.state.touched.email = true;
+            this.validate('email');
+        });
+
+        phoneNumberInput.addEventListener('input', (e) => {
+            this.state.phoneNumber = e.target.value;
+            this.validate('phoneNumber');
+        });
+
+        phoneNumberInput.addEventListener('blur', () => {
+            this.state.touched.phoneNumber = true;
+            this.validate('phoneNumber');
+        });
+
+        form.addEventListener('submit', (e) => {
+            e.preventDefault();
+            this.handleSubmit();
+        });
+    }
+
+    validate(fieldName) {
+        const input = document.getElementById(fieldName);
+        const fieldContainer = input.closest('.form-field');
+        const errorElement = document.getElementById(`${fieldName}Error`);
+        let isValid = true;
+        let errorMessage = '';
+
+        if (fieldName === 'fullName') {
+            if (!this.state.fullName.trim()) {
+                errorMessage = 'Full name is required';
+                isValid = false;
+            } else if (this.state.fullName.trim().length < 2) {
+                errorMessage = 'Full name must be at least 2 characters';
+                isValid = false;
+            }
+        } else if (fieldName === 'email') {
+            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+            if (!this.state.email.trim()) {
+                errorMessage = 'Email address is required';
+                isValid = false;
+            } else if (!emailRegex.test(this.state.email)) {
+                errorMessage = 'Please enter a valid email address';
