+        const isEmailValid = this.validate('email');
+        const isPhoneValid = this.validate('phoneNumber');
+
+        return isFullNameValid && isEmailValid && isPhoneValid;
+    }
+
+    handleSubmit() {
+        this.state.submitted = true;
+        this.state.touched = {
